  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <main id="main">
      <div class="app" data-component="ImagePreviewPage">
        <section class="hero" aria-labelledby="page-title">
          <h1 id="page-title">Image preview</h1>
          <p class="subtext">Review the photo before deciding whether to keep it in your library.</p>
        </section>

        <section class="preview-card" aria-labelledby="image-title">
          <div class="image-frame">
            <img
              src="https://images.unsplash.com/photo-1519681393784-d120267933ba?auto=format&fit=crop&w=1400&q=80"
              alt="Mountain ridge under a blue night sky with illuminated clouds"
            />
          </div>

          <div class="caption-row">
            <div class="meta">
              <h2 id="image-title">Blue hour mountains</h2>
              <p>Saved in your library just now.</p>
            </div>

            <button class="trigger" type="button" data-dialog-target="delete-confirmation">
              Delete image
            </button>
          </div>
        </section>
      </div>
    </main>

    <dialog id="delete-confirmation" aria-labelledby="delete-title" aria-describedby="delete-description">
      <form method="dialog" class="dialog-shell">
        <div class="dialog-heading">
          <h2 id="delete-title">Delete this image?</h2>
          <p id="delete-description">
            This will remove the image from your library. You can&apos;t undo this action.
          </p>
        </div>

        <div class="dialog-actions">
          <button type="submit" class="secondary" value="cancel">Cancel</button>
          <button type="submit" class="danger" value="delete">Delete</button>
        </div>
      </form>
    </dialog>

    <script>
      (() => {
        const dialog = document.getElementById("delete-confirmation");
        const trigger = document.querySelector(".trigger");
        const deleteButton = dialog.querySelector(".danger");

        trigger.addEventListener("click", () => {
          if (!dialog.open) {
            dialog.showModal();
          }
          deleteButton.focus();
        });

        dialog.addEventListener("close", () => {
          trigger.focus();
        });
      })();
    </script>
  </body>
</html>
