        background: var(--bg-elevated);
        border: 1px solid var(--border-strong);
        transform: translateY(-200%);
        transition: transform 160ms ease;
        z-index: 1000;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      main {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 4rem 1.25rem;
      }

      .app {
        width: min(100%, 56rem);
        display: grid;
        gap: 1.5rem;
      }

      .hero {
        display: grid;
        gap: 0.5rem;
      }

