        margin: 0;
        font-size: clamp(2rem, 4vw, 3.3rem);
        line-height: 1.05;
        letter-spacing: -0.03em;
      }

      .subtext {
        margin: 0;
        color: var(--muted);
        max-width: 54ch;
        line-height: 1.6;
      }

