        display: grid;
        gap: 1rem;
        padding: 1rem;
        border-radius: 1.5rem;
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02)), var(--bg-elevated);
        border: 1px solid var(--border);
        box-shadow: var(--shadow);
      }

