      }

      .trigger {
        background: linear-gradient(180deg, #2a3557, #1c2642);
        border-color: var(--border-strong);
      }

      .trigger:hover {
        background: linear-gradient(180deg, #334067, #22304f);
      }

      dialog {
        width: min(92vw, 31rem);
