        background: linear-gradient(180deg, #11182c 0%, #0d1324 100%);
        color: var(--text);
        box-shadow: var(--shadow);
      }

      dialog::backdrop {
        background: rgba(3, 6, 15, 0.72);
        backdrop-filter: blur(6px);
