        margin-top: 1.25rem;
        flex-wrap: wrap;
      }

      .secondary {
        background: transparent;
        border-color: var(--border);
      }

      .secondary:hover {
        background: #18223b;
      }

      .danger {
        background: linear-gradient(180deg, #ff7a7a, #d94b4b);
        color: #1b0b0b;
        border-color: #ff9a9a;
      }

      .danger:hover {
        background: linear-gradient(180deg, #ff8b8b, #e05858);
